// Both exports are `@solid-primitives/utils`' `asArray`, declared as that
// package declares it. The contract closes `returns` over its three returns
// for `asArray` only; `asArrayOpen` is the control, identical except that its
// `returns` is left open.
//
// The signatures are `tsc`-clean on purpose: mapping over the result is well
// typed under these declarations, so nothing here duplicates a type diagnostic.
export declare const asArray: <T>(value: T) => (T extends any[] ? T[number] : NonNullable<T>)[];
export declare const asArrayOpen: <T>(value: T) => (T extends any[] ? T[number] : NonNullable<T>)[];

// ADR 0116. Both are `@solid-primitives/utils@7.0.0-next.4`'s `accessWith`,
// declared exactly as that package declares it; the contract closes `returns`
// over what calling the argument returned and the argument itself for
// `accessWith` only, and `accessWithOpen` leaves it open.
type AnyFunction = (...args: any[]) => any;
export declare function accessWith<T>(valueOrFn: T, ...args: T extends AnyFunction ? Parameters<T> : never): T extends AnyFunction ? ReturnType<T> : T;
export declare function accessWithOpen<T>(valueOrFn: T, ...args: T extends AnyFunction ? Parameters<T> : never): T extends AnyFunction ? ReturnType<T> : T;
